<?php use Hls\Http\View as V; ?><section class="panel"><p>Nomor: <strong><?= V::escape($row['issue_ref']) ?></strong></p><p>Tanggal: <?= V::escape($row['issue_date']) ?> · Cabang: <?= V::escape($row['branch_code']) ?> · Gudang Asal: <?= V::escape($row['warehouse_code'] ? $row['warehouse_code'].' - '.$row['warehouse_name'] : 'Belum dialokasikan') ?></p><p>Penerima: <?= V::escape((string)$row['recipient']) ?> · Status: <?= V::escape($row['status']) ?> · Referensi: <?= V::escape((string)$row['document_ref']) ?></p><?php if($row['status']==='DRAFT'&&$access->can('inventory.issue.post')): ?><form method="post" action="<?= $this->url('/inventory/issue-post') ?>" onsubmit="return confirm('Posting barang keluar? Stok gudang asal akan berkurang.');"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="button button-primary">Posting Barang Keluar</button></form><?php endif ?></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Satuan</th><th>Kuantitas</th></tr></thead><tbody><?php foreach($lines as $l): ?><tr><td><?= V::escape($l['item_code'].' - '.$l['item_name']) ?></td><td><?= V::escape($l['unit_name']) ?></td><td><?= number_format((float)$l['quantity'],3,',','.') ?></td></tr><?php endforeach ?></tbody></table></div></section><a class="button" href="<?= $this->url('/inventory/issues') ?>">Kembali</a>
